//
// KR260 system prototype: the minimal ariane_kr260 wrapper plus the Zynq
// UltraScale+ PS DDR path generated by create_kr260_ps_ddr_bd.tcl.

import kr260_addr_pkg::*;

module ariane_kr260_system (
    input  logic tck_i,
    input  logic tms_i,
    input  logic tdi_i,
    input  logic trst_ni,
    output logic tdo_o
);

  logic        pl_clk;
  logic        pl_rst_n;

  logic [4:0]  axi_awid;
  logic [63:0] axi_awaddr;
  logic [7:0]  axi_awlen;
  logic [2:0]  axi_awsize;
  logic [1:0]  axi_awburst;
  logic        axi_awlock;
  logic [3:0]  axi_awcache;
  logic [2:0]  axi_awprot;
  logic [3:0]  axi_awqos;
  logic [5:0]  axi_awatop;
  logic [3:0]  axi_awregion;
  logic [63:0] axi_awuser;
  logic        axi_awvalid;
  logic        axi_awready;
  logic [63:0] axi_wdata;
  logic [7:0]  axi_wstrb;
  logic        axi_wlast;
  logic [63:0] axi_wuser;
  logic        axi_wvalid;
  logic        axi_wready;
  logic [5:0]  ps_bid;
  logic [1:0]  axi_bresp;
  logic        axi_bvalid;
  logic        axi_bready;
  logic [4:0]  axi_arid;
  logic [63:0] axi_araddr;
  logic [7:0]  axi_arlen;
  logic [2:0]  axi_arsize;
  logic [1:0]  axi_arburst;
  logic        axi_arlock;
  logic [3:0]  axi_arcache;
  logic [2:0]  axi_arprot;
  logic [3:0]  axi_arqos;
  logic [3:0]  axi_arregion;
  logic [63:0] axi_aruser;
  logic        axi_arvalid;
  logic        axi_arready;
  logic [5:0]  ps_rid;
  logic [63:0] axi_rdata;
  logic [1:0]  axi_rresp;
  logic        axi_rlast;
  logic        axi_rvalid;
  logic        axi_rready;

  // The CVA6 SoC view reserves 0x8000_0000..0xbfff_ffff for DRAM. ZynqMP's
  // DDR_LOW aperture is 0x0000_0000..0x7fff_ffff. Translate the selected 1 GiB
  // window explicitly rather than silently dropping address bits.
  logic [63:0] ps_awaddr_translated;
  logic [63:0] ps_araddr_translated;
  assign ps_awaddr_translated = axi_awaddr - CVA6_DDR_BASE;
  assign ps_araddr_translated = axi_araddr - CVA6_DDR_BASE;

  ariane_kr260 i_ariane_kr260 (
      .clk_i              ( pl_clk       ),
      .rst_ni             ( pl_rst_n     ),
      .tck_i,
      .tms_i,
      .tdi_i,
      .trst_ni,
      .tdo_o,
      .m_axi_mem_awid     ( axi_awid     ),
      .m_axi_mem_awaddr   ( axi_awaddr   ),
      .m_axi_mem_awlen    ( axi_awlen    ),
      .m_axi_mem_awsize   ( axi_awsize   ),
      .m_axi_mem_awburst  ( axi_awburst  ),
      .m_axi_mem_awlock   ( axi_awlock   ),
      .m_axi_mem_awcache  ( axi_awcache  ),
      .m_axi_mem_awprot   ( axi_awprot   ),
      .m_axi_mem_awqos    ( axi_awqos    ),
      .m_axi_mem_awatop   ( axi_awatop   ),
      .m_axi_mem_awregion ( axi_awregion ),
      .m_axi_mem_awuser   ( axi_awuser   ),
      .m_axi_mem_awvalid  ( axi_awvalid  ),
      .m_axi_mem_awready  ( axi_awready  ),
      .m_axi_mem_wdata    ( axi_wdata    ),
      .m_axi_mem_wstrb    ( axi_wstrb    ),
      .m_axi_mem_wlast    ( axi_wlast    ),
      .m_axi_mem_wuser    ( axi_wuser    ),
      .m_axi_mem_wvalid   ( axi_wvalid   ),
      .m_axi_mem_wready   ( axi_wready   ),
      .m_axi_mem_bid      ( ps_bid[4:0]  ),
      .m_axi_mem_bresp    ( axi_bresp    ),
      .m_axi_mem_buser    ( '0           ),
      .m_axi_mem_bvalid   ( axi_bvalid   ),
      .m_axi_mem_bready   ( axi_bready   ),
      .m_axi_mem_arid     ( axi_arid     ),
      .m_axi_mem_araddr   ( axi_araddr   ),
      .m_axi_mem_arlen    ( axi_arlen    ),
      .m_axi_mem_arsize   ( axi_arsize   ),
      .m_axi_mem_arburst  ( axi_arburst  ),
      .m_axi_mem_arlock   ( axi_arlock   ),
      .m_axi_mem_arcache  ( axi_arcache  ),
      .m_axi_mem_arprot   ( axi_arprot   ),
      .m_axi_mem_arqos    ( axi_arqos    ),
      .m_axi_mem_arregion ( axi_arregion ),
      .m_axi_mem_aruser   ( axi_aruser   ),
      .m_axi_mem_arvalid  ( axi_arvalid  ),
      .m_axi_mem_arready  ( axi_arready  ),
      .m_axi_mem_rid      ( ps_rid[4:0]  ),
      .m_axi_mem_rdata    ( axi_rdata    ),
      .m_axi_mem_rresp    ( axi_rresp    ),
      .m_axi_mem_rlast    ( axi_rlast    ),
      .m_axi_mem_ruser    ( '0           ),
      .m_axi_mem_rvalid   ( axi_rvalid   ),
      .m_axi_mem_rready   ( axi_rready   )
  );

  ariane_kr260_ps_bd_wrapper i_ps_ddr (
      .clk_o                 ( pl_clk                    ),
      .rst_no                ( pl_rst_n                  ),
      .S_AXI_CVA6_awid       ( {1'b0, axi_awid}          ),
      .S_AXI_CVA6_awaddr     ( ps_awaddr_translated[48:0]),
      .S_AXI_CVA6_awlen      ( axi_awlen                 ),
      .S_AXI_CVA6_awsize     ( axi_awsize                ),
      .S_AXI_CVA6_awburst    ( axi_awburst               ),
      .S_AXI_CVA6_awlock     ( axi_awlock                ),
      .S_AXI_CVA6_awcache    ( axi_awcache               ),
      .S_AXI_CVA6_awprot     ( axi_awprot                ),
      .S_AXI_CVA6_awqos      ( axi_awqos                 ),
      .S_AXI_CVA6_awuser     ( 1'b0                      ),
      .S_AXI_CVA6_awvalid    ( axi_awvalid               ),
      .S_AXI_CVA6_awready    ( axi_awready               ),
      .S_AXI_CVA6_wdata      ( axi_wdata                 ),
      .S_AXI_CVA6_wstrb      ( axi_wstrb                 ),
      .S_AXI_CVA6_wlast      ( axi_wlast                 ),
      .S_AXI_CVA6_wvalid     ( axi_wvalid                ),
      .S_AXI_CVA6_wready     ( axi_wready                ),
      .S_AXI_CVA6_bid        ( ps_bid                    ),
      .S_AXI_CVA6_bresp      ( axi_bresp                 ),
      .S_AXI_CVA6_bvalid     ( axi_bvalid                ),
      .S_AXI_CVA6_bready     ( axi_bready                ),
      .S_AXI_CVA6_arid       ( {1'b0, axi_arid}          ),
      .S_AXI_CVA6_araddr     ( ps_araddr_translated[48:0]),
      .S_AXI_CVA6_arlen      ( axi_arlen                 ),
      .S_AXI_CVA6_arsize     ( axi_arsize                ),
      .S_AXI_CVA6_arburst    ( axi_arburst               ),
      .S_AXI_CVA6_arlock     ( axi_arlock                ),
      .S_AXI_CVA6_arcache    ( axi_arcache               ),
      .S_AXI_CVA6_arprot     ( axi_arprot                ),
      .S_AXI_CVA6_arqos      ( axi_arqos                 ),
      .S_AXI_CVA6_aruser     ( 1'b0                      ),
      .S_AXI_CVA6_arvalid    ( axi_arvalid               ),
      .S_AXI_CVA6_arready    ( axi_arready               ),
      .S_AXI_CVA6_rid        ( ps_rid                    ),
      .S_AXI_CVA6_rdata      ( axi_rdata                 ),
      .S_AXI_CVA6_rresp      ( axi_rresp                 ),
      .S_AXI_CVA6_rlast      ( axi_rlast                 ),
      .S_AXI_CVA6_rvalid     ( axi_rvalid                ),
      .S_AXI_CVA6_rready     ( axi_rready                )
  );

  // These checks document and verify the assumptions made at the standard
  // AXI4 PS boundary. They are simulation/formal checks and synthesize away.
`ifndef SYNTHESIS
  always_ff @(posedge pl_clk) begin
    if (pl_rst_n && axi_awvalid) begin
      assert (axi_awaddr >= CVA6_DDR_BASE && axi_awaddr < CVA6_DDR_END);
      assert (axi_awatop == '0);
      assert (axi_awlock == 1'b0);
      assert (axi_awregion == '0 && axi_awuser == '0);
    end
    if (pl_rst_n && axi_wvalid) assert (axi_wuser == '0);
    if (pl_rst_n && axi_arvalid) begin
      assert (axi_araddr >= CVA6_DDR_BASE && axi_araddr < CVA6_DDR_END);
      assert (axi_arlock == 1'b0);
      assert (axi_arregion == '0 && axi_aruser == '0);
    end
    if (pl_rst_n && axi_bvalid) assert (ps_bid[5] == 1'b0);
    if (pl_rst_n && axi_rvalid) assert (ps_rid[5] == 1'b0);
  end
`endif

endmodule
